    assert close(w, [10.057737570678835, 16.287970035752164, 16.650221604267102, 17.873770421242888, 15.971394446423474]) and close(h, [1.0, -0.2994578994886752, -1.2701428350285022, -1.7128478623207886, -0.7541056403000839]) and close(l, [0.0, 16.000000000000004, 37.0, 60.12622957875711, 83.02860555357653])
